PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR CONSTANT
    LOW_LIMIT : INT := 10;
    HIGH_LIMIT : INT := 90;
END_VAR

IF Level >= HIGH_LIMIT THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSIF Level <= LOW_LIMIT THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

END_PROGRAM

