    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR CONSTANT
    IDLE : INT := 0;
    FILL : INT := 1;
    HEAT : INT := 2;
    REACT : INT := 3;
    DRAIN : INT := 4;
END_VAR

IF NOT EStop THEN
    State := IDLE;
ELSIF StartBatch AND Level >= LIQ_MIN THEN
    CASE State OF
        IDLE:
            IF Level < LVL_HIGH THEN
                State := FILL;
            ELSE
                State := HEAT;
            END_IF;
        FILL:
            IF Level >= LVL_HIGH THEN
                State := HEAT;
            END_IF;
        HEAT:
            IF Level < LIQ_MIN OR Temp >= TEMP_SET THEN
                State := REACT;
            END_IF;
        REACT:
            IF Time >= PT_REACT THEN
                State := DRAIN;
            END_IF;
        DRAIN:
            IF Level <= LVL_LOW THEN
                State := IDLE;
            END_IF;
    END_CASE;
END_IF;

CASE State OF
    IDLE:
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    FILL:
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    HEAT:
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
    REACT:
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
    DRAIN:
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;
END_CASE;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR

IF NOT EStop THEN
    State := 0;
ELSIF StartBatch AND Level >= LIQ_MIN THEN
    CASE State OF
        0: IF Level >= LVL_HIGH THEN State := 1 END_IF;
        1: IF Level >= LVL_HIGH THEN State := 2 END_IF;
        2: IF Temp >= TEMP_SET AND Level >= LIQ_MIN THEN State := 3 END_IF;
        3: IF Time >= PT_REACT THEN State := 4 END_IF;
        4: IF Level <= LVL_LOW THEN State := 0 END_IF;
    END_CASE
END_IF;

CASE State OF
    0: FillValve := FALSE; Heater := FALSE; Agitator := FALSE; DrainValve := FALSE;
    1: FillValve := Level < LVL_HIGH; Heater := FALSE; Agitator := FALSE; DrainValve := FALSE;
    2: FillValve := FALSE; Heater := Temp < TEMP_SET; Agitator := TRUE; DrainValve := FALSE;
    3: FillValve := FALSE; Heater := TRUE; Agitator := TRUE; DrainValve := FALSE;
    4: FillValve := FALSE; Heater := FALSE; Agitator := FALSE; DrainValve := Level > LVL_LOW;
END_CASE;

END_PROGRAM

PROGRAM garage
