PROGRAM tank_cycle
VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    LOW : INT := 10;
    HIGH : INT := 90;
END_VAR

IF NOT EStop THEN
    State := 0;
ELSIF Level >= HIGH AND State <> 2 THEN
    State := 2;
ELSIF Level <= LOW AND State = 2 THEN
    State := 0;
ELSIF StartCycle AND Level < HIGH AND State = 0 THEN
    State := 1;
END_IF;

CASE State OF
    0: // Idle
        Pump := FALSE;
        Valve := FALSE;
    1: // Filling
        Pump := Level < HIGH;
        Valve := FALSE;
    2: // Draining
        Pump := FALSE;
        Valve := Level > LOW;
END_CASE;

END_PROGRAM

