PROGRAM burner
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
    Flame : BOOL;
END_VAR
VAR_OUTPUT
    Fan : BOOL;
    Fuel : BOOL;
    Ignition : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    PT_PURGE : TIME := T#3s;
    PT_IGN : TIME := T#2s;
END_VAR

CASE State OF
    0:  // Off
        IF StopPB OR (NOT EStop) THEN
            State := 0;
        ELSIF StartPB AND EStop THEN
            State := 1;
        END_IF;

    1:  // Purge
        IF StopPB OR (NOT EStop) THEN
            State := 0;
        ELSIF Timer1.T >= PT_PURGE THEN
            State := 2;
        END_IF;
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;

    2:  // Ignite
        IF StopPB OR (NOT EStop) THEN
            State := 0;
        ELSIF Timer2.T >= PT_IGN THEN
            IF Flame THEN
                State := 3;
            ELSE
                State := 0;
            END_IF;
        END_IF;
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;

    3:  // Run
        IF StopPB OR (NOT EStop) OR NOT Flame THEN
            State := 0;
        END_IF;
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;

    ELSE
        State := 0;
END_CASE

IF NOT EStop THEN
    State := 0;
END_IF;

Timer1(IN := TRUE, PT := PT_PURGE);
Timer2(IN := TRUE, PT := PT_IGN);

END_PROGRAM

