PROGRAM pump_alt
VAR_INPUT
    Demand : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR
VAR
    Lead : INT;
    PrevDemand : BOOL;
END_VAR

IF NOT EStop THEN
    Lead := 0;
ELSIF Demand AND NOT PrevDemand THEN
    Lead := 1 - Lead;
END_IF;

PrevDemand := Demand;

CASE Lead OF
    0:
        Pump1 := Demand;
        Pump2 := FALSE;
    1:
        Pump1 := FALSE;
        Pump2 := Demand;
END_CASE;

END_PROGRAM

