PROGRAM gate
VAR_INPUT
    OpenCmd : BOOL;
    CloseCmd : BOOL;
    OpenLimit : BOOL;
    CloseLimit : BOOL;
    Obstruction : BOOL;
END_VAR
VAR_OUTPUT
    MotorOpen : BOOL;
    MotorClose : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    IDLE : INT := 0;
    OPENING : INT := 1;
    CLOSING : INT := 2;
END_VAR

CASE State OF
    IDLE:
        MotorOpen := FALSE;
        MotorClose := FALSE;
        IF OpenCmd AND NOT OpenLimit THEN
            State := OPENING;
        ELSIF CloseCmd AND NOT (CloseLimit OR Obstruction) THEN
            State := CLOSING;
        END_IF;
    OPENING:
        MotorOpen := TRUE;
        MotorClose := FALSE;
        IF OpenLimit OR Obstruction THEN
            State := IDLE;
        END_IF;
    CLOSING:
        MotorOpen := FALSE;
        MotorClose := TRUE;
        IF CloseLimit OR Obstruction THEN
            State := IDLE;
        END_IF;
END_CASE;

END_PROGRAM

