    0:
        IF NOT EStop THEN
            IF StartPB AND NOT StopPB THEN
                State := 1;
            END_IF;
        END_IF;
    1:
        IF NOT EStop THEN
            IF StartPB AND NOT StopPB THEN
                State := 2;
            END_IF;
        END_IF;
    2:
        IF NOT EStop THEN
            IF StartPB AND NOT StopPB THEN
                State := 3;
            END_IF;
        END_IF;
    3:
        IF Not EStop THEN
            IF StartPB AND NOT StopPB THEN
                State := 3;
            END_IF;
        END_IF;
END_CASE;

CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;
    2:
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;
    3:
        C1 := TRUE;
        C2 := TRUE;
        C3 := TRUE;
END_CASE;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
