            IF StartPB AND NOT StopPB AND State >= 1 THEN
                State := 2;
            END_IF;
        END_IF;
    2:
        IF NOT EStop THEN
            IF StartPB AND NOT StopPB AND State >= 2 THEN
                State := 3;
            END_IF;
        END_IF;
    3:
        IF NOT EStop THEN
            IF StartPB AND NOT StopPB AND State >= 3 THEN
                State := 3;
            END_IF;
        END_IF;
END_CASE;

